package envdoc

import (
	"fmt"
	"slices"
	"sort"
	"strings"
	"unicode/utf8"

	"github.com/stergiotis/boxer/public/config/env"
)

// envFileWidth is the column the comment lines of RenderEnvFile wrap at.
const envFileWidth = 78

// EnvFileOptions customises RenderEnvFile.
type EnvFileOptions struct {
	// GeneratorPath names the command that rendered the file in its
	// header (e.g. "public/app env gen-envfile"). Empty omits it.
	GeneratorPath string

	// Export prefixes every assignment with `export `, so the file can be
	// sourced by a POSIX shell without `set -a`. Some env-file readers
	// (docker's --env-file among them) do not accept the prefix.
	Export bool

	// Lookup, when set, supplies the values a variable holds: one it
	// reports as set is written as an active assignment of that value
	// instead of a commented-out default. A Sensitive variable's value is
	// never written; its line stays commented and says it is set. Nil
	// renders a template in which every line is commented out.
	Lookup func(name string) (value string, set bool)
}

// RenderEnvFile renders specs as a commented environment file: one
// assignment per variable, grouped by category and sorted by name, each
// preceded by its description, type, allowed values, CLI flag and
// declaring package as comments (ADR-0009 §4). Unless opts.Lookup says
// otherwise an assignment is commented out and carries the default, so
// the file changes nothing until a line is uncommented. Values are quoted
// for a POSIX shell. The output has no timestamp: two renders of one
// registry with one Lookup are byte-identical.
func RenderEnvFile(specs []env.Spec, opts EnvFileOptions) (out string) {
	byCat := map[env.CategoryE][]env.Spec{}
	cats := make([]env.CategoryE, 0, 32)
	for _, s := range specs {
		_, seen := byCat[s.Category]
		if !seen {
			cats = append(cats, s.Category)
		}
		byCat[s.Category] = append(byCat[s.Category], s)
	}
	sort.Slice(cats, func(i, j int) bool {
		return string(cats[i]) < string(cats[j])
	})

	var b strings.Builder
	header := "Environment variables declared in the env-var registry (ADR-0009)."
	if opts.GeneratorPath != "" {
		header += " Generated by `" + opts.GeneratorPath + "`."
	}
	writeComment(&b, header)
	b.WriteString("#\n")
	writeComment(&b, "A line of the form #NAME=value is a commented-out assignment of the "+
		"variable's default; uncomment it to set the variable. A variable left "+
		"commented out, or set to an empty value, reads as unset and its default applies.")
	b.WriteString("#\n")
	if opts.Export {
		writeComment(&b, "Load into a POSIX shell with: . ./FILE")
	} else {
		writeComment(&b, "Load into a POSIX shell with: set -a; . ./FILE; set +a")
	}
	b.WriteString("#\n")
	writeComment(&b, fmt.Sprintf("%s across %s.", plural(len(specs), "variable"), plural(len(cats), "category")))

	prefix := ""
	if opts.Export {
		prefix = "export "
	}
	for _, c := range cats {
		list := byCat[c]
		sort.Slice(list, func(i, j int) bool {
			return list[i].Name < list[j].Name
		})
		b.WriteString("\n# " + strings.Repeat("=", envFileWidth-2) + "\n")
		writeComment(&b, fmt.Sprintf("%s (%d)", c, len(list)))
		b.WriteString("# " + strings.Repeat("=", envFileWidth-2) + "\n")
		for _, s := range list {
			b.WriteString("\n")
			writeEnvFileEntry(&b, s, prefix, opts.Lookup)
		}
	}
	out = b.String()
	return
}

func writeEnvFileEntry(b *strings.Builder, s env.Spec, prefix string, lookup func(string) (string, bool)) {
	desc := strings.Join(strings.Fields(s.Description), " ")
	if desc != "" {
		writeComment(b, desc)
	}
	facts := make([]string, 0, 3)
	if s.Type != "" {
		facts = append(facts, "type: "+string(s.Type))
	}
	if s.CliFlagName != "" {
		facts = append(facts, "flag: --"+s.CliFlagName)
	}
	var value string
	var set bool
	if lookup != nil {
		value, set = lookup(s.Name)
		if value == "" {
			// The registry reads empty as unset (ADR-0009, update of
			// 2026-08-28); an active empty assignment would say otherwise.
			set = false
		}
	}
	if set && s.Default != "" {
		// The assignment line shows the default only while it is
		// commented out.
		facts = append(facts, "default: "+shellQuote(s.Default))
	}
	if len(facts) > 0 {
		writeComment(b, strings.Join(facts, "; "))
	}
	if len(s.Allowed) > 0 {
		writeComment(b, "one of: "+strings.Join(s.Allowed, " | "))
	}
	if s.Sensitive {
		writeComment(b, "sensitive: holds a secret; keep a file that sets it private")
	}
	if s.Origin.Package != "" {
		// Not wrapped: a package path is one word, and split from its
		// label it no longer reads as one fact.
		b.WriteString("# declared in: " + s.Origin.Package + "\n")
	}
	switch {
	case set && s.Sensitive:
		writeComment(b, "set in the environment; the value is not written")
		fmt.Fprintf(b, "#%s%s=\n", prefix, s.Name)
	case set:
		if len(s.Allowed) > 0 && !slices.Contains(s.Allowed, value) {
			writeComment(b, "the value below is not one of the allowed values; it reads as the default")
		}
		fmt.Fprintf(b, "%s%s=%s\n", prefix, s.Name, shellQuote(value))
	default:
		fmt.Fprintf(b, "#%s%s=%s\n", prefix, s.Name, shellQuote(s.Default))
	}
}

func plural(n int, noun string) (out string) {
	switch {
	case n == 1:
		out = "1 " + noun
	case strings.HasSuffix(noun, "y"):
		out = fmt.Sprintf("%d %sies", n, strings.TrimSuffix(noun, "y"))
	default:
		out = fmt.Sprintf("%d %ss", n, noun)
	}
	return
}

// writeComment writes text as `# ` lines wrapped at envFileWidth. A word
// longer than the width gets a line of its own.
func writeComment(b *strings.Builder, text string) {
	const lead = "# "
	width := envFileWidth - len(lead)
	line := make([]string, 0, 16)
	n := 0
	flush := func() {
		b.WriteString(lead + strings.Join(line, " ") + "\n")
		line = line[:0]
		n = 0
	}
	for _, w := range strings.Fields(text) {
		if n > 0 && n+1+utf8.RuneCountInString(w) > width {
			flush()
		}
		if n > 0 {
			n++
		}
		n += utf8.RuneCountInString(w)
		line = append(line, w)
	}
	if len(line) > 0 {
		flush()
	}
}

// shellQuote returns v as a POSIX shell word: unchanged when it holds
// only characters the shell does not interpret, else single-quoted with
// each embedded single quote closed, escaped and reopened.
func shellQuote(v string) (out string) {
	if v == "" {
		return ""
	}
	safe := true
	for _, r := range v {
		if !isShellSafe(r) {
			safe = false
			break
		}
	}
	if safe {
		return v
	}
	out = "'" + strings.ReplaceAll(v, "'", `'\''`) + "'"
	return
}

func isShellSafe(r rune) (ok bool) {
	switch {
	case r >= 'a' && r <= 'z', r >= 'A' && r <= 'Z', r >= '0' && r <= '9':
		return true
	}
	return strings.ContainsRune("_@%+=:,./-", r)
}
